using Junexis.Studio.Abstractions;

namespace Junexis.Studio.Host;

/// <summary>
/// A deterministic suggestion generated by the OMWiA extension based on IDE events.
/// </summary>
/// <param name="Category">Category of the suggestion (e.g. "Workspace", "Build", "File").</param>
/// <param name="Message">Human-readable suggestion text.</param>
/// <param name="TimestampUtc">When the suggestion was generated.</param>
public sealed record OmwiaSuggestion(string Category, string Message, DateTime TimestampUtc);

/// <summary>
/// View-model for the OMWiA panel. Subscribes to IDE events and generates
/// deterministic suggestions. No AI/LLM — purely rule-based.
/// </summary>
public sealed class OmwiaPanelViewModel
{
    private readonly IEventBus _eventBus;
    private readonly List<OmwiaSuggestion> _suggestions = new();

    /// <summary>
    /// Current list of suggestions (newest first).
    /// </summary>
    public IReadOnlyList<OmwiaSuggestion> Suggestions
    {
        get { lock (_suggestions) return _suggestions.ToList(); }
    }

    /// <summary>
    /// Raised when a new suggestion is added.
    /// </summary>
    public event Action<OmwiaSuggestion>? SuggestionAdded;

    /// <summary>
    /// Initializes a new <see cref="OmwiaPanelViewModel"/> and subscribes to IDE events.
    /// </summary>
    /// <param name="eventBus">Event bus for subscribing to IDE events.</param>
    /// <exception cref="ArgumentNullException">When <paramref name="eventBus"/> is null.</exception>
    public OmwiaPanelViewModel(IEventBus eventBus)
    {
        _eventBus = eventBus ?? throw new ArgumentNullException(nameof(eventBus));

        _eventBus.Subscribe<WorkspaceOpenedEvent>(OnWorkspaceOpened);
        _eventBus.Subscribe<DocumentSaved>(OnDocumentSaved);
        _eventBus.Subscribe<BuildRequestedEvent>(OnBuildRequested);
    }

    /// <summary>
    /// Clears all suggestions.
    /// </summary>
    public void Clear()
    {
        lock (_suggestions) _suggestions.Clear();
    }

    /// <summary>
    /// Unsubscribes from IDE events. Call on extension shutdown.
    /// </summary>
    public void Dispose()
    {
        _eventBus.Unsubscribe<WorkspaceOpenedEvent>(OnWorkspaceOpened);
        _eventBus.Unsubscribe<DocumentSaved>(OnDocumentSaved);
        _eventBus.Unsubscribe<BuildRequestedEvent>(OnBuildRequested);
    }

    private void AddSuggestion(string category, string message)
    {
        var suggestion = new OmwiaSuggestion(category, message, DateTime.UtcNow);
        lock (_suggestions)
        {
            _suggestions.Insert(0, suggestion);
        }
        SuggestionAdded?.Invoke(suggestion);
    }

    private void OnWorkspaceOpened(WorkspaceOpenedEvent e)
    {
        AddSuggestion("Workspace", $"Workspace opened: {e.RootPath}. Consider running a build to check project health.");
    }

    private void OnDocumentSaved(DocumentSaved e)
    {
        var ext = System.IO.Path.GetExtension(e.Path);
        if (string.Equals(ext, ".cs", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(ext, ".jnx", StringComparison.OrdinalIgnoreCase))
        {
            AddSuggestion("File", $"File saved: {e.Path}. Auto-build may be triggered.");
        }
    }

    private void OnBuildRequested(BuildRequestedEvent e)
    {
        AddSuggestion("Build", "Build requested. Review diagnostics after completion.");
    }
}

/// <summary>
/// OMWiA minimal extension: registers an OMWiA panel, subscribes to IDE events,
/// and publishes deterministic suggestions. No dependency on <see cref="IAssistantService"/>
/// — this is the rule-based suggestion layer.
/// </summary>
public sealed class OmwiaExtension : IJunexisExtension
{
    private OmwiaPanelViewModel? _viewModel;

    /// <inheritdoc />
    public string Id => "junexis.omwia";

    /// <inheritdoc />
    public void Initialize(IHostContext context)
    {
        _viewModel = new OmwiaPanelViewModel(context.EventBus);

        context.Panels.RegisterPanel(
            "junexis.omwia",
            PanelType.Tool,
            () => _viewModel,
            title: "OMWiA",
            dockGroup: DockGroup.Right);

        context.Commands.Register("omwia.clear", () => _viewModel.Clear(),
            menuPath: null, displayName: "Clear Suggestions", category: "OMWiA", contextTarget: "junexis.omwia");

        context.Output.Write("OMWiA", "OmwiaExtension loaded — deterministic suggestions active.");
    }

    /// <inheritdoc />
    public void Shutdown()
    {
        _viewModel?.Dispose();
        _viewModel = null;
    }
}
